sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiValues = {
        grouped_publishers: []
    };

    try {
        // Get publishers from system property
        var topPublishersProperty = gs.getProperty('Top publishers property');

        if (topPublishersProperty) {
            // Split comma-separated values into an array
            var publishersArray = topPublishersProperty.split(',');

            // Trim whitespace from each value and add to result
            for (var i = 0; i < publishersArray.length; i++) {
                var publisherID = publishersArray[i].trim();
                if (publisherID) {
                    kpiValues.grouped_publishers.push(publisherID);
                }
            }
        } else {
            gs.log("Warning: Top publisher property system property not found or empty");
        }
    } catch (error) {
        var errorMessage = error && error.message ? error.message : "Unknown error";
        gs.error("Error: " + errorMessage);
    }
    gs.log('top publishers',JSON.stringify(kpiValues,null,2))
    return kpiValues;
}
